import { CloudFormationCustomResourceEvent, CloudFormationCustomResourceFailedResponse, CloudFormationCustomResourceSuccessResponse } from 'aws-lambda';
/**
 * Lambda handler function that processes CloudFormation custom resource events.
 *
 * On Create/Update events:
 * - Inserts a test customer into the tenants table with the DEFAULT_UUID
 * - Sets up basic customer properties including a reference to the development sandbox DB
 *
 * On Delete events:
 * - Takes no action as the table itself will be deleted by CloudFormation
 *
 * @param event - The CloudFormation custom resource event (Create/Update/Delete)
 * @returns A success or failure response for CloudFormation
 */
export declare const handler: (event: CloudFormationCustomResourceEvent) => Promise<CloudFormationCustomResourceSuccessResponse | CloudFormationCustomResourceFailedResponse>;
